class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        operations = 0
        i = 0
        n = len(word)
        while i < n - 1:
            current_char = word[i]
            next_char = word[i + 1]
            if current_char == next_char or abs(ord(current_char) - ord(next_char)) == 1:
                # Find the next possible character that is not almost-equal
                for candidate in range(ord('a'), ord('z') + 1):
                    candidate_char = chr(candidate)
                    if candidate_char != current_char and abs(ord(candidate_char) - ord(current_char)) > 1:
                        # Check if changing next_char to candidate_char resolves the issue
                        if i + 1 == n - 1 or (abs(ord(candidate_char) - ord(word[i + 2])) > 1 if i + 2 < n else True):
                            word = word[:i+1] + candidate_char + word[i+2:]
                            operations += 1
                            break
                i += 2
            else:
                i += 1
        return operations
